/* ==========================================================================
   PART 2  -  LAYOUT, GRID AND UTILITIES  (replaces Bootstrap)
   ========================================================================== */

/* ---------- 1. RESET (Bootstrap "reboot") ---------- */
body{
  margin:0;
  font-size:1rem;
  font-weight:400;
  line-height:1.5;
  text-align:left;
  -webkit-text-size-adjust:100%;
}

h1,h2,h3,h4,h5,h6{
  margin-top:0;
  margin-bottom:.5rem;
  font-weight:500;
  line-height:1.2;
}
h1{font-size:2.5rem}
h2{font-size:2rem}
h3{font-size:1.75rem}
h4{font-size:1.5rem}
h5{font-size:1.25rem}
h6{font-size:1rem}

p{margin-top:0; margin-bottom:1rem}

ul,ol{
  margin-top:0;
  margin-bottom:1rem;
  padding-left:2rem;
}

figure{margin:0 0 1rem}

a{color:inherit; text-decoration:none}

img,svg{vertical-align:middle}

label{display:inline-block}

button,input,select,textarea{
  margin:0;
  font-family:inherit;
  font-size:inherit;
  line-height:inherit;
}
button{text-transform:none}
button,[type=button],[type=submit]{-webkit-appearance:button}
button:not(:disabled){cursor:pointer}

hr{
  margin:1rem 0;
  border:0;
  border-top:1px solid;
  opacity:.25;
}

/* ---------- 2. CONTAINER ---------- */
.container{
  --gx:1.5rem;
  width:100%;
  margin-right:auto;
  margin-left:auto;
  padding-right:calc(var(--gx) * .5);   /* 12px */
  padding-left:calc(var(--gx) * .5);
}
@media (min-width:576px) { .container{max-width:540px} }
@media (min-width:768px) { .container{max-width:720px} }
@media (min-width:992px) { .container{max-width:960px} }
@media (min-width:1200px){ .container{max-width:1140px} }
@media (min-width:1400px){ .container{max-width:1320px} }

/* ---------- 3. GRID: row + columns ---------- */
/* Bootstrap puts the gap on the columns as padding, and pulls the row out
   sideways with negative margins, so the outer edges stay flush.           */
.row{
  --gx:1.5rem;
  --gy:0;
  display:flex;
  flex-wrap:wrap;
  margin-top:calc(-1 * var(--gy));
  margin-right:calc(-.5 * var(--gx));
  margin-left:calc(-.5 * var(--gx));
}
.row > *{
  flex-shrink:0;
  width:100%;
  max-width:100%;
  margin-top:var(--gy);
  padding-right:calc(var(--gx) * .5);
  padding-left:calc(var(--gx) * .5);
}

/* gutter sizes */
.g-2{--gx:.5rem;  --gy:.5rem}
.g-3{--gx:1rem;   --gy:1rem}
.g-4{--gx:1.5rem; --gy:1.5rem}
.g-5{--gx:3rem;   --gy:3rem}

/* column widths */
.col-6 {flex:0 0 auto; width:50%}

@media (min-width:576px){
  .col-sm-3{flex:0 0 auto; width:25%}
  .col-sm-5{flex:0 0 auto; width:41.66666667%}
  .col-sm-7{flex:0 0 auto; width:58.33333333%}
}
@media (min-width:768px){
  .col-md-2{flex:0 0 auto; width:16.66666667%}
  .col-md-3{flex:0 0 auto; width:25%}
  .col-md-4{flex:0 0 auto; width:33.33333333%}
  .col-md-6{flex:0 0 auto; width:50%}
}
@media (min-width:992px){
  .col-lg-4 {flex:0 0 auto; width:33.33333333%}
  .col-lg-6 {flex:0 0 auto; width:50%}
  .col-lg-8 {flex:0 0 auto; width:66.66666667%}
  .col-lg-11{flex:0 0 auto; width:91.66666667%}
}
@media (min-width:1200px){
  .col-xl-3{flex:0 0 auto; width:25%}
}

/* --------------------------------------------------------------------------
   UTILITY CLASSES (sections 4-9)

   Note the !important on every line below. Bootstrap does exactly the same
   thing, and it matters: a button like

       <button class="bgrd btn px-4 py-3 fs-6">

   has both .btn (which sets its own padding) and .px-4 / .py-3. All are
   single classes, so without !important whichever is written last in the
   file would win. Bootstrap makes utilities always win, so the button gets
   the 16px/24px padding it is supposed to have.
   -------------------------------------------------------------------------- */

/* ---------- 4. DISPLAY ---------- */
.d-none       {display:none !important}
.d-block      {display:block !important}
.d-flex       {display:flex !important}
.d-inline-flex{display:inline-flex !important}

@media (min-width:576px){ .d-sm-flex{display:flex !important} }
@media (min-width:768px){ .d-md-block{display:block !important} }
@media (min-width:992px){
  .d-lg-flex{display:flex !important}
  .d-lg-none{display:none !important}
}

/* ---------- 5. FLEX ---------- */
.flex-column{flex-direction:column !important}
.flex-wrap  {flex-wrap:wrap !important}
.flex-fill  {flex:1 1 auto !important}

.align-items-start {align-items:flex-start !important}
.align-items-center{align-items:center !important}

.justify-content-center {justify-content:center !important}
.justify-content-between{justify-content:space-between !important}

.gap-1{gap:.25rem !important}
.gap-2{gap:.5rem !important}
.gap-3{gap:1rem !important}
.gap-4{gap:1.5rem !important}

/* ---------- 6. SIZING ---------- */
.w-100{width:100% !important}
.h-100{height:100% !important}

/* ---------- 7. SPACING ---------- */
/* margin-bottom */
.mb-0{margin-bottom:0 !important}
.mb-1{margin-bottom:.25rem !important}
.mb-2{margin-bottom:.5rem !important}
.mb-3{margin-bottom:1rem !important}
.mb-4{margin-bottom:1.5rem !important}
.mb-5{margin-bottom:3rem !important}
/* margin-top */
.mt-2{margin-top:.5rem !important}
.mt-3{margin-top:1rem !important}
.mt-4{margin-top:1.5rem !important}
.mt-5{margin-top:3rem !important}
/* margin left / right ("s" = start, "e" = end) */
.me-1{margin-right:.25rem !important}
.me-2{margin-right:.5rem !important}
.ms-1{margin-left:.25rem !important}
.me-auto{margin-right:auto !important}
.ms-auto{margin-left:auto !important}
.mx-auto{margin-right:auto !important; margin-left:auto !important}
/* padding */
.p-3{padding:1rem !important}
.p-4{padding:1.5rem !important}
.pt-4{padding-top:1.5rem !important}
.px-2{padding-right:.5rem !important;  padding-left:.5rem !important}
.px-3{padding-right:1rem !important;   padding-left:1rem !important}
.px-4{padding-right:1.5rem !important; padding-left:1.5rem !important}
.py-1{padding-top:.25rem !important; padding-bottom:.25rem !important}
.py-2{padding-top:.5rem !important;  padding-bottom:.5rem !important}
.py-3{padding-top:1rem !important;   padding-bottom:1rem !important}

/* ---------- 8. TEXT ---------- */
.text-start {text-align:left !important}
.text-center{text-align:center !important}
.text-end   {text-align:right !important}

.fs-5{font-size:1.25rem !important}   /* 20px */
.fs-6{font-size:1rem !important}      /* 16px */

.fw-semibold{font-weight:600 !important}
.fw-bold    {font-weight:700 !important}
.fw-700     {font-weight:700 !important}

.text-primary{color:#0d6efd !important}
.text-warning{color:#ffc107 !important}

/* ---------- 9. BORDERS / POSITION ---------- */
.border-bottom{border-bottom:1px solid #dee2e6 !important}
.position-relative{position:relative !important}

/* ---------- 10. BUTTON base ---------- */
/* The theme's own .bgrd / .boc classes supply the colours and the 12px
   radius, so this only needs Bootstrap's structural bits.                 */
.btn{
  display:inline-block;
  padding:.375rem .75rem;
  font-size:1rem;
  font-weight:400;
  line-height:1.5;
  text-align:center;
  text-decoration:none;
  vertical-align:middle;
  background-color:transparent;
  border:1px solid transparent;
  border-radius:.375rem;
  cursor:pointer;
  user-select:none;
}

.btn-close{
  box-sizing:content-box;
  width:1em;
  height:1em;
  padding:.25em;
  background:transparent
    url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23fff'%3e%3cpath d='M.293.293a1 1 0 0 1 1.414 0L8 6.586 14.293.293a1 1 0 1 1 1.414 1.414L9.414 8l6.293 6.293a1 1 0 0 1-1.414 1.414L8 9.414l-6.293 6.293a1 1 0 0 1-1.414-1.414L6.586 8 .293 1.707a1 1 0 0 1 0-1.414z'/%3e%3c/svg%3e")
    center/1em auto no-repeat;
  border:0;
  border-radius:.375rem;
  opacity:.5;
}
.btn-close:hover{opacity:.75}

/* ---------- 11. ACCORDION base ---------- */
/* The theme restyles the colours/radius in style.css; this supplies the
   structure and the little chevron arrow.                                 */
.accordion-item{
  background-color:transparent;
  border:1px solid rgba(255,255,255,.07);
}
.accordion-header{margin-bottom:0}

.accordion-button{
  position:relative;
  display:flex;
  align-items:center;
  width:100%;
  padding:1rem 1.25rem;
  font-size:1rem;
  color:inherit;
  text-align:left;
  background-color:transparent;
  border:0;
  border-radius:0;
  overflow-anchor:none;
}
.accordion-button::after{
  flex-shrink:0;
  width:1.25rem;
  height:1.25rem;
  margin-left:auto;
  content:"";
  background-image:url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23a78bfa'%3e%3cpath fill-rule='evenodd' d='M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708z'/%3e%3c/svg%3e");
  background-repeat:no-repeat;
  background-size:1.25rem;
  transition:transform .2s ease-in-out;
}
.accordion-button:not(.collapsed)::after{transform:rotate(-180deg)}
.accordion-body{padding:1rem 1.25rem}

/* ---------- 12. COLLAPSE ---------- */
/* Bootstrap's JS adds/removes .show to open a panel. With no JS the state
   is fixed: panels marked .show stay open, the rest stay closed — which is
   exactly how the page looks when it first loads.                          */
.collapse:not(.show){display:none}

/* ---------- 13. OFFCANVAS ---------- */
/* Slide-in panels (mobile menu, login panel). They are opened by Bootstrap's
   JS, so with no JS they simply stay off screen.                           */
.offcanvas{
  position:fixed;
  bottom:0;
  z-index:1045;
  display:flex;
  flex-direction:column;
  max-width:100%;
  visibility:hidden;
  background-clip:padding-box;
  outline:0;
}
.offcanvas-end{
  top:0;
  right:0;
  width:400px;
  border-left:1px solid rgba(255,255,255,.13);
  transform:translateX(100%);
}
.offcanvas-body{
  flex-grow:1;
  padding:1rem;
  overflow-y:auto;
}



/* ==========================================================================
   PART 3  -  THEME STYLES
   ========================================================================== */

:root {
  --bg: #08080f;
  --bg2: #0d0d1a;
  --bg3: #12121f;
  --sf: #16162a;
  --bd: rgba(255, 255, 255, 0.07);
  --bd2: rgba(255, 255, 255, 0.13);
  --tx: #f0f0ff;
  --tx2: #a8a8c8;
  --tx3: #6b6b8a;
  --pur: #8b5cf6;
  --blu: #3b82f6;
  --grad: linear-gradient(135deg, #8b5cf6, #3b82f6);
  --nav: 68px;
  --dsb: 240px;
}
.lm {
  --bg: #fafafe;
  --bg2: #f0f0ff;
  --bg3: #e8e8ff;
  --sf: #fff;
  --bd: rgba(99, 71, 246, 0.1);
  --bd2: rgba(99, 71, 246, 0.2);
  --tx: #0f0f1a;
  --tx2: #3d3d5c;
  --tx3: #7878a0;
}
*,
*::before,
*::after {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: "Space Grotesk", sans-serif;
  background: var(--bg);
  color: var(--tx);
  overflow-x: hidden;
  transition: background 0.3s, color 0.3s;
}
a {
  text-decoration: none;
  color: inherit;
}
.gt {
  background: var(--grad);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.slbl {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.73rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--pur);
  margin-bottom: 14px;
}
.slbl::before {
  content: "";
  width: 20px;
  height: 1.5px;
  background: var(--grad);
}
.stitle {
  font-size: clamp(1.85rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.14;
  letter-spacing: -0.025em;
  margin-bottom: 14px;
}
.ssub {
  font-size: 1rem;
  color: var(--tx2);
  max-width: 560px;
}
.aur {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
  z-index: 0;
}
.aur-a {
  width: 600px;
  height: 600px;
  background: radial-gradient(
    circle,
    rgba(139, 92, 246, 0.22),
    transparent 70%
  );
}
.aur-b {
  width: 500px;
  height: 500px;
  background: radial-gradient(
    circle,
    rgba(59, 130, 246, 0.18),
    transparent 70%
  );
}
.gc {
  background: var(--sf);
  border: 1px solid var(--bd);
  border-radius: 18px;
  transition: 0.3s;
}
.gc:hover {
  border-color: rgba(139, 92, 246, 0.3);
  transform: translateY(-3px);
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.25);
}
.bgrd {
  background: var(--grad);
  border: none;
  color: #fff;
  font-family: "Space Grotesk", sans-serif;
  font-weight: 600;
  border-radius: 12px;
  transition: 0.25s;
  cursor: pointer;
}
.bgrd:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(139, 92, 246, 0.4);
  color: #fff;
}
.boc {
  background: transparent;
  border: 1px solid var(--bd2);
  color: var(--tx);
  font-family: "Space Grotesk", sans-serif;
  font-weight: 500;
  border-radius: 12px;
  transition: 0.25s;
  cursor: pointer;
}
.boc:hover {
  border-color: var(--pur);
  background: rgba(139, 92, 246, 0.08);
  color: var(--tx);
}
.rv {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 0.65s, transform 0.65s;
}
.rv.in {
  opacity: 1;
  transform: none;
}
.sp {
  padding: 90px 0;
}
/* NAVBAR */
#nbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1050;
  height: var(--nav);
  background: rgba(8, 8, 15, 0.78);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--bd);
  display: flex;
  align-items: center;
  transition: background 0.3s, box-shadow 0.3s;
}
.lm #nbar {
  background: rgba(250, 250, 254, 0.88);
}
#nbar.scr {
  background: rgba(8, 8, 15, 0.96);
  box-shadow: 0 4px 28px rgba(0, 0, 0, 0.4);
}
.lm #nbar.scr {
  background: rgba(250, 250, 254, 0.97);
}
.logo-i {
  width: 34px;
  height: 34px;
  background: var(--grad);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.95rem;
  flex-shrink: 0;
}
.nav-link {
  color: var(--tx2) !important;
  font-weight: 500;
  font-size: 0.9rem;
  padding: 6px 14px !important;
  border-radius: 8px;
  transition: 0.2s !important;
}
.nav-link:hover {
  color: var(--tx) !important;
  background: rgba(255, 255, 255, 0.06) !important;
}
.lm .nav-link:hover {
  background: rgba(0, 0, 0, 0.05) !important;
}
#mbmenu {
  position: fixed;
  top: var(--nav);
  left: 0;
  right: 0;
  z-index: 1049;
  background: rgba(8, 8, 15, 0.98);
  backdrop-filter: blur(20px);
  padding: 14px 20px 20px;
  border-bottom: 1px solid var(--bd);
  display: none;
}
.lm #mbmenu {
  background: rgba(250, 250, 254, 0.98);
}
#mbmenu.open {
  display: block;
}
/* HERO */
#hero {
  min-height: 100vh;
  padding-top: var(--nav);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hbadge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 14px 5px 8px;
  border-radius: 100px;
  background: rgba(139, 92, 246, 0.12);
  border: 1px solid rgba(139, 92, 246, 0.3);
  font-size: 0.78rem;
  font-weight: 600;
  color: #a78bfa;
  margin-bottom: 22px;
}
.bdot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--pur);
  animation: bpls 2s infinite;
  flex-shrink: 0;
}
.h1 {
  font-size: clamp(2.4rem, 6.5vw, 5rem);
  font-weight: 700;
  line-height: 1.09;
  letter-spacing: -0.03em;
  margin-bottom: 22px;
}
.tlog {
  opacity: 0.4;
  filter: grayscale(1);
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--tx2);
  transition: 0.3s;
}
.tlog:hover {
  opacity: 0.75;
  filter: none;
}
.dwrap {
  border-radius: 26px;
  overflow: hidden;
  background: var(--sf);
  border: 1px solid var(--bd2);
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.65), 0 0 40px rgba(139, 92, 246, 0.2);
