.db-bottom {
  padding: 16px 12px;
  border-top: 1px solid var(--bd);
}
/* DB MAIN */
.db-main {
  margin-left: var(--dsb);
  padding-top: var(--nav);
  min-height: 100vh;
}
.db-content {
  padding: 28px;
}
/* DB SECTIONS */
.db-section {
  display: none;
}
.db-section.active {
  display: block;
}
/* STAT CARDS */
.db-stat-card {
  background: var(--sf);
  border: 1px solid var(--bd);
  border-radius: 16px;
  padding: 22px;
  position: relative;
  overflow: hidden;
  transition: 0.3s;
}
.db-stat-card:hover {
  border-color: rgba(139, 92, 246, 0.25);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}
.db-stat-card::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--grad);
  opacity: 0.6;
}
.db-stat-val {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 4px;
}
.db-stat-lbl {
  font-size: 0.78rem;
  color: var(--tx3);
  margin-bottom: 6px;
}
.db-stat-delta {
  font-size: 0.75rem;
  font-weight: 600;
}
.delta-up {
  color: #34d399;
}
.delta-dn {
  color: #f87171;
}
/* AI CHAT */
.chat-wrap {
  background: var(--sf);
  border: 1px solid var(--bd);
  border-radius: 18px;
  display: flex;
  flex-direction: column;
  height: 520px;
  overflow: hidden;
}
.chat-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--bd);
  display: flex;
  align-items: center;
  gap: 12px;
}
.chat-ai-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--grad);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 0.95rem;
  flex-shrink: 0;
}
.chat-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  color: #34d399;
  font-weight: 600;
}
.chat-body {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  scroll-behavior: smooth;
}
.chat-body::-webkit-scrollbar {
  width: 4px;
}
.chat-body::-webkit-scrollbar-track {
  background: transparent;
}
.chat-body::-webkit-scrollbar-thumb {
  background: var(--bd2);
  border-radius: 4px;
}
.msg {
  max-width: 80%;
  padding: 10px 14px;
  border-radius: 14px;
  font-size: 0.875rem;
  line-height: 1.55;
  word-break: break-word;
}
.msg-ai {
  background: var(--bg3);
  border: 1px solid var(--bd);
  color: var(--tx);
  align-self: flex-start;
  border-radius: 4px 14px 14px 14px;
}
.msg-user {
  background: var(--grad);
  color: #fff;
  align-self: flex-end;
  border-radius: 14px 14px 4px 14px;
}
.msg-time {
  font-size: 0.68rem;
  color: var(--tx3);
  margin-top: 4px;
}
.typing-ind {
  display: flex;
  gap: 4px;
  padding: 10px 14px;
  background: var(--bg3);
  border: 1px solid var(--bd);
  border-radius: 4px 14px 14px 14px;
  align-self: flex-start;
  align-items: center;
}
.typing-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--pur);
  animation: tbounce 0.9s infinite;
}
.typing-dot:nth-child(2) {
  animation-delay: 0.15s;
}
.typing-dot:nth-child(3) {
  animation-delay: 0.3s;
}
.chat-input-wrap {
  padding: 14px 16px;
  border-top: 1px solid var(--bd);
  display: flex;
  gap: 10px;
  align-items: flex-end;
}
.chat-inp {
  flex: 1;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1px solid var(--bd2);
  background: var(--bg3);
  color: var(--tx);
  font-size: 0.875rem;
  font-family: "Space Grotesk", sans-serif;
  outline: none;
  resize: none;
  max-height: 100px;
  line-height: 1.5;
  transition: 0.2s;
}
.chat-inp:focus {
  border-color: var(--pur);
}
.chat-send {
  width: 40px;
  height: 40px;
  border-radius: 12px;
  background: var(--grad);
  border: none;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: 0.2s;
  flex-shrink: 0;
}
.chat-send:hover {
  transform: scale(1.05);
  box-shadow: 0 4px 16px rgba(139, 92, 246, 0.4);
}
.chat-send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}
/* AGENT CARD */
.agent-card {
  background: var(--sf);
  border: 1px solid var(--bd);
  border-radius: 16px;
  padding: 20px;
  transition: 0.3s;
}
.agent-card:hover {
  border-color: rgba(139, 92, 246, 0.3);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}
.agent-status {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
.ag-online {
  background: #34d399;
  box-shadow: 0 0 8px #34d399;
}
.ag-busy {
  background: #8b5cf6;
  box-shadow: 0 0 8px #8b5cf6;
}
.ag-offline {
  background: #6b6b8a;
}
/* TABLE */
.db-table {
  width: 100%;
  border-collapse: collapse;
}
.db-table th {
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--tx3);
  padding: 10px 16px;
  border-bottom: 1px solid var(--bd);
  text-align: left;
}
.db-table td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--bd);
  font-size: 0.875rem;
  color: var(--tx2);
}
.db-table tr:last-child td {
  border-bottom: none;
}
.db-table tr:hover td {
  background: rgba(139, 92, 246, 0.04);
}
/* SETTINGS */
.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0;
  border-bottom: 1px solid var(--bd);
}
.setting-row:last-child {
  border-bottom: none;
}
.toggle-switch {
  position: relative;
  width: 44px;
  height: 24px;
}
.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}
.toggle-thumb {
  position: absolute;
  inset: 0;
  background: var(--bd2);
  border-radius: 100px;
  cursor: pointer;
  transition: 0.3s;
}
.toggle-thumb::before {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  left: 3px;
  top: 3px;
  background: #fff;
  border-radius: 50%;
  transition: 0.3s;
}
.toggle-switch input:checked + .toggle-thumb {
  background: var(--grad);
}
.toggle-switch input:checked + .toggle-thumb::before {
  transform: translateX(20px);
}
/* NOTIFICATION */
.notif-item {
  display: flex;
  gap: 12px;
  padding: 14px;
  border-radius: 12px;
  background: var(--sf);
  border: 1px solid var(--bd);
  margin-bottom: 10px;
  transition: 0.2s;
}
.notif-item:hover {
  border-color: rgba(139, 92, 246, 0.2);
}
.notif-ico {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
/* DROPDOWN PANELS */
.db-dropdown {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  z-index: 2000;
  background: var(--bg2);
  border: 1px solid var(--bd2);
  border-radius: 18px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
  min-width: 340px;
  overflow: hidden;
  animation: fadeIn 0.2s ease;
  display: none;
}
.db-dropdown.open {
  display: block;
}
.dd-header {
  padding: 16px 18px;
  border-bottom: 1px solid var(--bd);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.dd-header-title {
  font-weight: 700;
  font-size: 0.95rem;
}
.dd-close {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  border: 1px solid var(--bd2);
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--tx3);
  cursor: pointer;
  font-size: 0.8rem;
  transition: 0.2s;
}
.dd-close:hover {
  border-color: var(--pur);
  color: var(--pur);
}
.dd-body {
  padding: 14px;
  max-height: 380px;
  overflow-y: auto;
}
.dd-body::-webkit-scrollbar {
  width: 4px;
}
.dd-body::-webkit-scrollbar-thumb {
  background: var(--bd2);
  border-radius: 4px;
}
.notif-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #8b5cf6;
  flex-shrink: 0;
  margin-top: 5px;
}
.notif-dot.read {
  background: var(--bd2);
}
.notif-unread {
  background: rgba(139, 92, 246, 0.06);
  border-color: rgba(139, 92, 246, 0.2);
}
/* PROFILE DROPDOWN */
.profile-dd {
  min-width: 260px;
}
.profile-dd-top {
  padding: 18px;
  border-bottom: 1px solid var(--bd);
  display: flex;
  align-items: center;
  gap: 12px;
}
.profile-menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  font-size: 0.875rem;
  color: var(--tx2);
  cursor: pointer;
  transition: 0.2s;
  border-radius: 10px;
  margin: 2px 8px;
  border: none;
  background: transparent;
  width: calc(100% - 16px);
  font-family: "Space Grotesk", sans-serif;
  text-align: left;
}
.profile-menu-item i {
  width: 18px;
  text-align: center;
  font-size: 0.9rem;
}
.profile-menu-item:hover {
  background: rgba(139, 92, 246, 0.1);
  color: var(--tx);
}
.profile-menu-item.danger:hover {
  background: rgba(248, 113, 113, 0.1);
  color: #f87171;
}
.profile-dd-footer {
  padding: 10px 8px;
  border-top: 1px solid var(--bd);
}
/* MOBILE DB */
@media (max-width: 991px) {
  .db-sidebar {
    transform: translateX(-100%);
    transition: 0.3s;
  }
  .db-sidebar.mob-open {
    transform: translateX(0);
  }
  .db-main {
    margin-left: 0;
  }
  .db-top {
    left: 0;
  }
}
/* KEYFRAMES */
@keyframes bpls {
  0%,
  100% {
    box-shadow: 0 0 6px var(--pur);
  }
  50% {
    box-shadow: 0 0 14px var(--pur);
  }
}
@keyframes bgrow {
  from {
    transform: scaleY(0);
    opacity: 0;
  }
  to {
    transform: scaleY(1);
    opacity: 0.75;
  }
}
@keyframes tbounce {
  0%,
  60%,
  100% {
    transform: translateY(0);
  }
  30% {
    transform: translateY(-5px);
  }
}
@keyframes lscr {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}
@keyframes fadU {
  from {
    opacity: 0;
    transform: translateY(22px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes dinI {
  from {
    opacity: 0;
    transform: perspective(1200px) rotateX(5deg) translateY(28px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.afu {
  animation: fadU 0.8s ease both;
}
.adi {
  animation: dinI 1.1s ease 0.35s both;
}
.rv {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 0.65s, transform 0.65s;
}
.rv.in {
  opacity: 1;
  transform: none;
}
@media (max-width: 575px) {
  .h1 {
    font-size: 2.2rem;
  }
  .stitle {
    font-size: 1.8rem;
  }
  #lofc {
    width: 100%;
  }
  .db-top-search {
    display: none;
  }
  .db-content {
    padding: 16px;
  }
}



/* ==========================================================================
   PART 4  -  STATIC-STATE ADJUSTMENTS (no JavaScript)
   ========================================================================== */

/* ---------- 1. Scroll reveal ---------- */
/* style.css sets .rv { opacity:0 } and JavaScript added the class .in
   once the element scrolled into view. With no JavaScript that class is
   never added, so every .rv element would stay invisible.
   Here we simply show them.                                               */
.rv{
  opacity:1;
  transform:none;
}

/* ---------- 2. Counters ---------- */
/* Numbers that were counted up by JavaScript already contain their final
   text in the HTML, so nothing to do — they display as-is.                */

/* ---------- 3. Light mode ---------- */
/* style.css has a .lm class (light mode) that JavaScript toggled on <html>.
   Without JavaScript the page stays in its default dark mode, which is how
   the original looks on load. The moon button is still shown, it just
   doesn't switch. Nothing to override here.                               */

/* ---------- 4. Typing dots in the hero chat ---------- */
/* Keep the three dots animating with CSS only (they were CSS already).    */

/* ---------- 5. Buttons that opened JS panels ---------- */
/* The Log in / Get Started buttons opened a Bootstrap offcanvas panel.
   They now do nothing, but should still look clickable.                   */
button.bgrd,
button.boc{
  cursor:pointer;
}

/* ---------- 6. Safety: never let a hidden panel cover the page ---------- */
/* Offcanvas panels and the video popup are JS-driven. Make sure they can
   never intercept clicks while they are closed.                           */
.offcanvas{
  pointer-events:none;
}
.offcanvas.show{
  pointer-events:auto;
  visibility:visible;
  transform:none;
}



